import json
import base64
import io
import contextlib
from pathlib import Path

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def execute_and_capture(code_str, global_scope):
    stdout_buf = io.StringIO()
    plt.close('all')
    
    with contextlib.redirect_stdout(stdout_buf):
        exec(code_str, global_scope)
        
    captured_stdout = stdout_buf.getvalue()
    outputs = []
    
    if captured_stdout:
        outputs.append({
            'name': 'stdout',
            'output_type': 'stream',
            'text': [line + chr(10) for line in captured_stdout.splitlines()]
        })
        
    for fig_num in plt.get_fignums():
        fig = plt.figure(fig_num)
        img_buf = io.BytesIO()
        fig.savefig(img_buf, format='png', bbox_inches='tight', dpi=fig.dpi)
        img_buf.seek(0)
        img_b64 = base64.b64encode(img_buf.getvalue()).decode('utf-8')
        outputs.append({
            'data': {
                'image/png': img_b64,
                'text/plain': [f'<Figure size {fig.get_size_inches()[0]*100}x{fig.get_size_inches()[1]*100} with {len(fig.axes)} Axes>']
            },
            'metadata': {},
            'output_type': 'display_data'
        })
        plt.close(fig)
        
    return outputs

def build_notebook(cell_code_list):
    cells = []
    global_scope = {}
    
    for i, code in enumerate(cell_code_list, start=1):
        clean_code = chr(10).join([line for line in code.strip().splitlines() if not line.strip().startswith('#') and '#' not in line])
        outputs = execute_and_capture(clean_code, global_scope)
        
        cells.append({
            'cell_type': 'code',
            'execution_count': i,
            'metadata': {},
            'outputs': outputs,
            'source': [line + chr(10) for line in clean_code.splitlines()]
        })
        
    nb = {
        'cells': cells,
        'metadata': {},
        'nbformat': 4,
        'nbformat_minor': 5
    }
    return nb

